<template><div class="pm-dashboard-layout" :class="{'pm-sidebar-hidden':hidden}"><AppSidebar :isOpen="open" @close="open=false"/><div class="pm-dashboard-main"><div class="pm-dashboard-topbar"><button class="pm-icon-btn pm-menu-btn" @click="open=!open">☰</button><button class="pm-icon-btn pm-hide-btn" @click="hidden=!hidden">←</button><div class="pm-topbar-page-title">Fuel Records</div><div class="pm-topbar-search"><input v-model="search" class="form-control" placeholder="Search..."/></div><div class="pm-topbar-actions"><button class="pm-icon-btn">♧<span class="pm-topbar-dot">5</span></button><button class="pm-icon-btn">✉</button></div><div class="pm-topbar-user"><div class="pm-topbar-avatar">JD</div><span class="pm-topbar-name">John Doe</span></div></div><div class="fuel-page"><header><div><h1>{{formMode?'New Fuel':'Fuel Records (Last 15 Days)'}}</h1><p>{{formMode?'Dashboard › Vehicle Management › Fuel › New Fuel':'All fuel transactions for vehicles in the last 15 days'}}</p></div><button class="btn btn-primary" @click="formMode=!formMode">{{formMode?'← Back to List':'+ Add Fuel Record'}}</button></header><template v-if="!formMode"><section class="fuel-summary"><article v-for="card in cards" :key="card.label"><span>{{card.icon}}</span><div>{{card.label}}<b>{{card.value}}</b><small>↗ {{card.change}} vs previous 15 days</small></div></article></section><section class="fuel-table"><h2>⛽ FUEL RECORDS LIST (Last 15 Days)</h2><table><thead><tr><th>#</th><th>Fuel Date</th><th>Vehicle No.</th><th>Make / Model</th><th>Driver</th><th>Fuel Type</th><th>UOM</th><th>Qty</th><th>Total ($)</th><th>Odometer (KM)</th><th>Station Name</th><th>Payment</th></tr></thead><tbody><tr v-for="(row,i) in records" :key="row.id"><td>{{i+1}}</td><td>{{date(row.fuel_date)}}</td><td>{{row.vehicle?.vehicle_number}}</td><td>{{row.vehicle?.make_brand}} {{row.vehicle?.model}}</td><td>{{row.driver?.driver_name||'—'}}</td><td>{{row.fuel_type}}</td><td>{{row.uom}}</td><td>{{row.quantity}}</td><td>${{row.total_cost}}</td><td>{{row.odometer_km}}</td><td>{{row.station_name}}</td><td>{{row.payment_method}}</td></tr></tbody></table></section></template><template v-else><div class="fuel-form"><section><h2>1 &nbsp; Record Information</h2><label>Record No.<input value="(Auto)" readonly></label><label>Fuel Date<input v-model="form.fuel_date" type="date"></label></section><section><h2>2 &nbsp; Vehicle Information</h2><label>Vehicle Number<select v-model="form.vehicle_id"><option value="">Select vehicle</option><option v-for="v in vehicles" :value="v.id">{{v.vehicle_number}} — {{v.make_brand}} {{v.model}}</option></select></label><label>Current Odometer (KM)<input v-model="form.odometer_km" type="number"></label></section><section><h2>5 &nbsp; Fuel Details</h2><label>Fuel Type<select v-model="form.fuel_type"><option>Diesel</option><option>Gasoline</option><option>Electric (EV)</option></select></label><label>UOM<select v-model="form.uom"><option>Liters</option><option>Gallons</option><option>kWh</option></select></label><label>Quantity<input v-model="form.quantity" type="number"></label><label>Price Per Unit<input v-model="form.unit_price" type="number"></label></section><section><h2>7 &nbsp; Payment Information</h2><label>Station Name<input v-model="form.station_name"></label><label>Payment Method<select v-model="form.payment_method"><option>Credit Card</option><option>Cash</option><option>Debit Card</option></select></label><label>Notes<textarea v-model="form.notes"></textarea></label></section></div><footer class="fuel-actions"><button class="btn btn-success" @click="save">Save</button><button class="btn btn-outline-secondary" @click="formMode=false">Cancel</button></footer></template></div></div></div></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import AppSidebar from'../components/AppSidebar.vue';import client from'../api/client';const open=ref(false),hidden=ref(false),formMode=ref(false),search=ref(''),records=ref([]),vehicles=ref([]);const form=reactive({vehicle_id:'',fuel_date:new Date().toISOString().slice(0,10),fuel_type:'Diesel',uom:'Liters',quantity:'',unit_price:'',odometer_km:'',station_name:'',payment_method:'Credit Card',notes:''});const cards=computed(()=>[{label:'Total Transactions',value:records.value.length,icon:'▣',change:'12%'},{label:'Total Quantity',value:records.value.reduce((n,x)=>n+Number(x.quantity||0),0).toFixed(2),icon:'▰',change:'8%'},{label:'Total Fuel Cost',value:'$ '+records.value.reduce((n,x)=>n+Number(x.total_cost||0),0).toFixed(2),icon:'◉',change:'10%'},{label:'Avg. Price / Unit',value:'$ 1.28',icon:'◈',change:'2%'},{label:'Vehicles Refueled',value:new Set(records.value.map(x=>x.vehicle_id)).size,icon:'⚙',change:'9%'}]);function date(v){return v?new Date(v).toLocaleDateString():'—'}async function load(){records.value=(await client.get('/fuel-records',{params:{per_page:50}})).data.data.data;vehicles.value=(await client.get('/vehicles',{params:{per_page:200}})).data.data.data}async function save(){await client.post('/fuel-records',{...form,vehicle_id:Number(form.vehicle_id),quantity:Number(form.quantity),unit_price:Number(form.unit_price),total_cost:Number(form.quantity)*Number(form.unit_price)});formMode.value=false;load()}onMounted(load)</script>
<style scoped>.fuel-page{padding:10px 0}.fuel-page header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.fuel-page h1{color:#081b79;font-size:28px;margin:0}.fuel-page p{margin:5px 0;color:#132276}.fuel-summary{display:grid;grid-template-columns:repeat(5,1fr);gap:16px;border:1px solid #e1eaf6;padding:16px}.fuel-summary article{display:flex;gap:13px;border:1px solid #e2eaf5;border-radius:8px;padding:18px;color:#102171}.fuel-summary span{font-size:32px}.fuel-summary b,.fuel-summary small{display:block;margin-top:8px}.fuel-summary b{font-size:22px}.fuel-summary small{color:#009955}.fuel-table{margin-top:12px;border:1px solid #e1eaf6;overflow:auto}.fuel-table h2{font-size:14px;padding:14px;margin:0}.fuel-table table{width:100%;border-collapse:collapse;font-size:11px}.fuel-table th,.fuel-table td{border:1px solid #e7edf7;padding:11px;white-space:nowrap}.fuel-table th{color:#071ca0}.fuel-form{display:grid;grid-template-columns:1fr 1.6fr;gap:12px}.fuel-form section{border:1px solid #e1e8f4;border-radius:8px;padding:16px}.fuel-form h2{font-size:15px;color:#063af0}.fuel-form label{display:inline-block;width:48%;padding:8px;font-size:12px;font-weight:700;color:#09207b}.fuel-form input,.fuel-form select,.fuel-form textarea{display:block;width:100%;height:35px;border:1px solid #d9e3f3;border-radius:4px;margin-top:6px}.fuel-actions{margin-top:12px;display:flex;gap:10px}@media(max-width:900px){.fuel-summary{grid-template-columns:1fr 1fr}.fuel-form{grid-template-columns:1fr}}</style>
